INSERT OR IGNORE INTO catalogue_pages (catalogue_id, page_num, text_content, char_count, has_extractable_text, search_text) VALUES ('24c796309c95d7fa', 314, '5400 Series - Grade 2 Standard Duty Surface Door Closer
WARRANTY Five-year warranty - maximum 200 lb. door weight 




