INSERT OR IGNORE INTO catalogue_pages (catalogue_id, page_num, text_content, char_count, has_extractable_text, search_text) VALUES ('24c796309c95d7fa', 521, ' Pocket - 9600 Comm. Series Pocket Door Frame Kits - 9628CS | 9629CSCS | 9630CS | 9631CS
